type State = Readonly<{ routes: Readonly<Record<string, string>>; version: number }>;

function addRoute(s: State, k: string, v: string): State {
  return Object.freeze({                       // runtime freeze (shallow)
    version: s.version + 1,
    routes: Object.freeze({ ...s.routes, [k]: v }),
  });
}

